 public void VerifyAutomaticRouting(){
  Action wait=()=>{DateTime end=DateTime.UtcNow.AddMilliseconds(700);while(DateTime.UtcNow<end){Application.DoEvents();Thread.Sleep(10);}};
  wait();if(!connected||engine.Error!=null)throw new Exception("Automatic initial connection: "+status.Text);
  var seed=new Layer{Name="Preserved",Original=new float[96000],Audio=new float[96000]};engine.Layers.Add(seed);
  int zoomInputs=devices.Items.Cast<SourceChoice>().Count(x=>x.Left==x.Right);if(zoomInputs!=14)throw new Exception("Zoom selector expected 14 mono inputs, got "+zoomInputs);
  devices.SetItemChecked(0,false);devices.SetItemChecked(1,true);wait();if(!connected||engine.Inputs.Count!=1||engine.Inputs[0].Left!=1)throw new Exception("Automatic channel swap failed: "+status.Text);
  outputs.SelectedIndex=1;wait();if(!connected||engine.Error!=null)throw new Exception("Automatic output swap failed: "+status.Text);
  channels.SelectedIndex=0;audioDebounce.Stop();loadingAudio=true;for(int i=0;i<devices.Items.Count;i++)devices.SetItemChecked(i,false);int cycle=-1;for(int i=0;i<devices.Items.Count;i++)if(devices.Items[i].ToString().IndexOf("Model:Cycles",StringComparison.OrdinalIgnoreCase)>=0){cycle=i;break;}if(cycle<0)throw new Exception("No Model:Cycles selector option");devices.SetItemChecked(cycle,true);for(int i=0;i<outputs.Items.Count;i++)if(outputs.Items[i].ToString().IndexOf("Model:Cycles",StringComparison.OrdinalIgnoreCase)>=0){outputs.SelectedIndex=i;break;}loadingAudio=false;QueueAudio();wait();
  if(!connected||engine.Error!=null)throw new Exception("Automatic Model:Cycles swap failed: "+status.Text);if(!engine.Layers.Contains(seed))throw new Exception("Switching lost the recorded layer");
